{
  "contract": "SimpleSalesEth",
  "closure": {
    "site_function": "buy",
    "site_call": ".safeTransferFrom",
    "functions": [
      "withdrawAllFailedCredits"
    ],
    "justification": "withdrawAllFailedCredits modifies exposed storage _ethBal and failedTransferCredits."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "withdrawAllFailedCredits"
    ],
    "nesting_bound": {
      "withdrawAllFailedCredits": 1
    }
  },
  "phases": {
    "function": "buy",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_safeTransferFrom"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_safeTransferFrom",
      "to_marker": "after_safeTransferFrom"
    },
    "post": {
      "name": "post",
      "from_marker": "after_safeTransferFrom",
      "to_marker": "end"
    },
    "linearization_point": "after_safeTransferFrom"
  },
  "ghost_state": [
    {
      "name": "_sum_failedTransferCredits",
      "sol_type": "uint256",
      "meaning": "Sum of all failed transfer credits",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum_failedTransferCredits == snapPre + inFlight",
    "stable_formula": "_sum_failedTransferCredits == snapPre",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum_failedTransferCredits <= _ethBal",
    "rule": "The sum of failed transfer credits must not exceed the available ETH balance."
  }
}
